begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.denied(stmt text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate in ('42601','42702','42703','42883','42P01') then raise;end if;raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpectedly allowed %',label;end$$;
insert into branches(id,code,name) values('cc910000-0000-0000-0000-000000000001','CG-A','Synthetic goals A'),('cc910000-0000-0000-0000-000000000002','CG-B','Synthetic goals B');
insert into auth.users(id,email) values('cc920000-0000-0000-0000-000000000001','goal-editor@example.invalid'),('cc920000-0000-0000-0000-000000000002','goal-approver@example.invalid');
insert into profiles(id,full_name,branch_id,active) values('cc920000-0000-0000-0000-000000000001','Synthetic editor','cc910000-0000-0000-0000-000000000001',true),('cc920000-0000-0000-0000-000000000002','Synthetic approver','cc910000-0000-0000-0000-000000000001',true);
insert into roles(id,code,name) values('cc930000-0000-0000-0000-000000000001','CG_EDITOR','Synthetic goal editor'),('cc930000-0000-0000-0000-000000000002','CG_APPROVER','Synthetic goal approver');
insert into role_permissions(role_id,permission_code) select r.id,p.permission_code from roles r cross join app_permissions p where r.code in ('CG_EDITOR','CG_APPROVER') and p.permission_code in ('COMMERCIAL_VIEW','COMMERCIAL_WRITE','SALES_VIEW','HYPERBARIC_VIEW');
insert into role_permissions(role_id,permission_code) values('cc930000-0000-0000-0000-000000000002','ACCESS_ADMIN');
insert into user_roles(user_id,role_id,branch_id) values('cc920000-0000-0000-0000-000000000001','cc930000-0000-0000-0000-000000000001','cc910000-0000-0000-0000-000000000001'),('cc920000-0000-0000-0000-000000000002','cc930000-0000-0000-0000-000000000002','cc910000-0000-0000-0000-000000000001');
-- Reuse the baseline global superuser: production deliberately allows only one.
select ur.user_id as approval_actor from user_roles ur join roles r on r.id=ur.role_id join profiles p on p.id=ur.user_id where r.code='SUPER_USUARIO' and p.active limit 1 \gset
insert into products(id,code,name,active) values('cc940000-0000-0000-0000-000000000001','CG-PG','Synthetic product PG',true),('cc940000-0000-0000-0000-000000000002','CG-PL','Synthetic product plasma',true);
select set_config('request.jwt.claim.sub','cc920000-0000-0000-0000-000000000001',true);
insert into operational_sales(id,sale_code,sale_date,branch_id,customer_name,status) values('cc950000-0000-0000-0000-000000000001','CG-OUT','2026-11-01','cc910000-0000-0000-0000-000000000001','Synthetic center','DESPACHADA'),('cc950000-0000-0000-0000-000000000002','CG-END','2026-11-30','cc910000-0000-0000-0000-000000000001','Synthetic center','DESPACHADA'),('cc950000-0000-0000-0000-000000000003','CG-PENDING','2026-11-15','cc910000-0000-0000-0000-000000000001','Synthetic center','PENDIENTE'),('cc950000-0000-0000-0000-000000000004','CG-CANCEL','2026-11-15','cc910000-0000-0000-0000-000000000001','Synthetic center','ANULADA'),('cc950000-0000-0000-0000-000000000005','CG-OTHER','2026-11-15','cc910000-0000-0000-0000-000000000002','Synthetic center','DESPACHADA');
insert into operational_sale_lines(sale_id,product_id,component_name,quantity,unit_price) values('cc950000-0000-0000-0000-000000000001','cc940000-0000-0000-0000-000000000001','PG',2.5,99999),('cc950000-0000-0000-0000-000000000001','cc940000-0000-0000-0000-000000000002','PLASMA',9,99999),('cc950000-0000-0000-0000-000000000002','cc940000-0000-0000-0000-000000000001','PG',1.5,0),('cc950000-0000-0000-0000-000000000003','cc940000-0000-0000-0000-000000000001','PG',20,0),('cc950000-0000-0000-0000-000000000004','cc940000-0000-0000-0000-000000000001','PG',20,0),('cc950000-0000-0000-0000-000000000005','cc940000-0000-0000-0000-000000000001','PG',20,0);
grant execute on all functions in schema pg_temp to authenticated,anon;
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
insert into commercial_goals(id,period_start,period_end,branch_id,metric,target_value,product_id,created_by) values('cc960000-0000-0000-0000-000000000001','2026-11-01','2026-11-30','cc910000-0000-0000-0000-000000000001','VENTAS_UNIDADES',3,'cc940000-0000-0000-0000-000000000001','cc920000-0000-0000-0000-000000000002');
select pg_temp.ok((select actual_quantity=4 and actual_value is null from vw_commercial_goal_progress where goal_id='cc960000-0000-0000-0000-000000000001'),'product achievement sums exact physical fractions including both date endpoints, excludes pending cancelled other branch and money');
select pg_temp.ok((select created_by=auth.uid() and approved_by is null and currency is null from commercial_goals where id='cc960000-0000-0000-0000-000000000001'),'goal creator stamped and new goal remains nonfinancial draft');
insert into commercial_goals(id,period_start,period_end,branch_id,metric,target_value,component_name) values('cc960000-0000-0000-0000-000000000002','2026-11-01','2026-11-30','cc910000-0000-0000-0000-000000000001','VENTAS_UNIDADES',5,'PLASMA');
select pg_temp.ok((select actual_quantity=9 from vw_commercial_goal_progress where goal_id='cc960000-0000-0000-0000-000000000002'),'component-scoped achievement excludes other products');
insert into commercial_goals(id,period_start,period_end,branch_id,metric,target_value) values('cc960000-0000-0000-0000-000000000003','2026-11-01','2026-11-30','cc910000-0000-0000-0000-000000000001','SESIONES_REALIZADAS',2);
select pg_temp.ok((select actual_quantity=0 from vw_commercial_goal_progress where goal_id='cc960000-0000-0000-0000-000000000003'),'sessions never add blood unit quantities');
select pg_temp.denied($q$update commercial_goals set approved_by=auth.uid(),approved_at=now() where id='cc960000-0000-0000-0000-000000000001'$q$,'ordinary editor cannot approve by direct update');
select pg_temp.denied($q$select approve_commercial_goal('cc960000-0000-0000-0000-000000000001')$q$,'ordinary editor cannot call approval RPC');
select pg_temp.denied($q$insert into commercial_goals(period_start,period_end,branch_id,metric,target_value) values('2026-11-01','2026-11-30','cc910000-0000-0000-0000-000000000002','VENTAS_UNIDADES',1)$q$,'goals cannot cross branch authorization');
select pg_temp.denied($q$insert into commercial_goals(period_start,period_end,branch_id,metric,target_value,product_id) values('2026-11-01','2026-11-30','cc910000-0000-0000-0000-000000000001','SESIONES_REALIZADAS',1,'cc940000-0000-0000-0000-000000000001')$q$,'session targets cannot use blood product scope');
select set_config('request.jwt.claim.sub',:'approval_actor',true);
select approve_commercial_goal('cc960000-0000-0000-0000-000000000001');
select pg_temp.ok((select approved_by=auth.uid() and approved_at is not null from commercial_goals where id='cc960000-0000-0000-0000-000000000001'),'authorized administrator approves with stamped actor');
select approve_commercial_goal('cc960000-0000-0000-0000-000000000001');
select pg_temp.ok((select revision=2 from commercial_goals where id='cc960000-0000-0000-0000-000000000001'),'approval retry is idempotent');
select set_config('request.jwt.claim.sub','cc920000-0000-0000-0000-000000000001',true);
update commercial_goals set target_value=6 where id='cc960000-0000-0000-0000-000000000001';
select pg_temp.ok((select approved_by is null and approved_at is null from commercial_goals where id='cc960000-0000-0000-0000-000000000001'),'changing a target invalidates its prior approval');
reset role;
delete from role_permissions where role_id='cc930000-0000-0000-0000-000000000001' and permission_code='SALES_VIEW';
set local role authenticated;
select pg_temp.ok((select actual_quantity is null from vw_commercial_goal_progress where goal_id='cc960000-0000-0000-0000-000000000001'),'missing source permissions are not presented as zero achievement');
reset role;
select pg_temp.ok((select count(*)>=5 from workflow_audit where table_name='commercial_goals' and actor_id in ('cc920000-0000-0000-0000-000000000001',:'approval_actor'::uuid)),'goal creation and approval changes produce audit evidence');
select pg_temp.ok((select reloptions @> array['security_invoker=true'] from pg_class where oid='vw_commercial_goal_progress'::regclass),'goal report view remains invoker');
select pg_temp.ok(not has_function_privilege('anon','approve_commercial_goal(uuid)','execute') and not has_table_privilege('anon','vw_commercial_goal_progress','select'),'anonymous goal approval and report access denied');
rollback;
